def transform(g):
    from collections import Counter, deque
    h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]; seen=set()
    for y in range(h):
      for x in range(w):
       if (y,x) in seen or g[y][x]==bg: continue
       c=g[y][x]; q=deque([(y,x)]); seen.add((y,x)); pts=[]
       while q:
        a,b=q.popleft(); pts.append((a,b))
        for da in (-1,0,1):
         for db in (-1,0,1):
          aa,bb=a+da,b+db
          if (da or db) and 0<=aa<h and 0<=bb<w and (aa,bb) not in seen and g[aa][bb]==c:
           seen.add((aa,bb)); q.append((aa,bb))
       ys=[a for a,b in pts]; xs=[b for a,b in pts]; t,B=min(ys),max(ys); l,R=min(xs),max(xs); area=(B-t+1)*(R-l+1)
       if area>=6 and len(pts)/area>=.70:
        for a in range(t,B+1):
         for b in range(l,R+1): out[a][b]=c
    return out
